import{_ as t,o,c as a,ax as s}from"./chunks/framework.Bnt0oLax.js";const p=JSON.parse('{"title":"Content Security","description":"Automated pre-publish security scanning the platform runs on every push, with no configuration needed; for guidance on which customization approach to choose, see Customization Guardrails","frontmatter":{"description":"Automated pre-publish security scanning the platform runs on every push, with no configuration needed; for guidance on which customization approach to choose, see Customization Guardrails"},"headers":[],"relativePath":"custom-widgets/v2/content-security.md","filePath":"custom-widgets/v2/content-security.md"}'),d={name:"custom-widgets/v2/content-security.md"};function r(i,e,n,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/custom-widgets/v2/content-security.md for this page in Markdown format</div><h1 id="content-security" tabindex="-1">Content Security <a class="header-anchor" href="#content-security" aria-label="Permalink to &quot;Content Security&quot;">​</a></h1><p>The platform automatically checks your extension code — widgets, scripts, and stylesheets — for security issues before publishing.</p><h2 id="what-the-platform-checks" tabindex="-1">What the Platform Checks <a class="header-anchor" href="#what-the-platform-checks" aria-label="Permalink to &quot;What the Platform Checks&quot;">​</a></h2><p>Every time you push code, the platform runs a series of checks before publishing your extensions. The sections below describe each check and the specific rules enforced.</p><h3 id="content-scanning" tabindex="-1">Content Scanning <a class="header-anchor" href="#content-scanning" aria-label="Permalink to &quot;Content Scanning&quot;">​</a></h3><p>Your code is scanned for patterns that could harm your community.</p><p><strong>Widgets</strong>: For source widgets (directories of files), the platform scans HTML and JavaScript files (<code>.html</code>, <code>.htm</code>, <code>.js</code>, <code>.mjs</code>, <code>.jsx</code>). CSS, images, and fonts are not scanned since they cannot contain executable patterns.</p><p><strong>Scripts</strong>: JavaScript files are scanned for executable patterns and credential exposure.</p><p><strong>Stylesheets</strong>: CSS files are scanned for unsafe rules or obfuscated content.</p><p>The platform checks for:</p><table tabindex="0"><thead><tr><th>Category</th><th>What It Detects</th><th>Example</th></tr></thead><tbody><tr><td>Crypto mining</td><td>Scripts that use visitor devices to mine cryptocurrency</td><td><code>CoinHive</code>, WebAssembly mining modules</td></tr><tr><td>Data exfiltration</td><td>Code that collects and sends user data to external servers</td><td>Keyloggers, cookie theft, form data harvesting</td></tr><tr><td>Phishing</td><td>Fake login forms or redirects that assign external URLs to <code>window.location</code></td><td>Credential harvesting pages, <code>window.location.href = &quot;https://...&quot;</code></td></tr><tr><td>Obfuscation</td><td>Heavily encoded or hidden code that obscures its purpose</td><td><code>eval(atob(...))</code>, <code>eval(String.fromCharCode(...))</code> chains</td></tr><tr><td>External script loading</td><td>Loading JavaScript from untrusted external sources</td><td><code>&lt;script src=&quot;...&quot;&gt;</code> from unknown domains</td></tr><tr><td>Credential exposure</td><td>Hardcoded secrets, API keys, tokens, or high-entropy strings</td><td>AWS keys, private keys, JWTs, <code>password = &quot;...&quot;</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Loading scripts from popular libraries like <code>cdn.jsdelivr.net</code>, <code>cdnjs.cloudflare.com</code>, <code>unpkg.com</code>, and <code>esm.sh</code> is allowed. Only untrusted sources are flagged.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Template-style placeholders like <code>${API_KEY}</code> are not flagged as credentials. UUIDs and sequential strings are also excluded from credential detection.</p></div><h3 id="security-headers" tabindex="-1">Security Headers <a class="header-anchor" href="#security-headers" aria-label="Permalink to &quot;Security Headers&quot;">​</a></h3><p>The platform adds browser-level protections to every widget response:</p><table tabindex="0"><thead><tr><th>Header</th><th>What It Does</th></tr></thead><tbody><tr><td>Content-Security-Policy</td><td>Controls which scripts, styles, and resources your widget can load</td></tr><tr><td>X-Content-Type-Options</td><td>Prevents the browser from guessing file types (blocks MIME sniffing)</td></tr><tr><td>Referrer-Policy</td><td>Limits what URL information is shared when navigating away</td></tr><tr><td>X-Frame-Options</td><td>Controls where your widget can be embedded</td></tr></tbody></table><h3 id="size-limits" tabindex="-1">Size Limits <a class="header-anchor" href="#size-limits" aria-label="Permalink to &quot;Size Limits&quot;">​</a></h3><p>Each extension has maximum size limits to ensure fast loading and prevent abuse:</p><ul><li>Widget directories: Limited to 100 files and 10 MB total</li><li>Individual files: 2 MB limit</li><li>Widget thumbnail image (<code>imageSrc</code>): 512 KB limit</li><li>Scripts and stylesheets: 2 MB per file (same limit as widget content files)</li></ul><h3 id="path-validation" tabindex="-1">Path Validation <a class="header-anchor" href="#path-validation" aria-label="Permalink to &quot;Path Validation&quot;">​</a></h3><p>Widget file paths must stay within the widget directory. Paths containing <code>../</code> (directory traversal) or starting with <code>/</code> (absolute paths) are rejected.</p><h3 id="immediate-removal" tabindex="-1">Immediate Removal <a class="header-anchor" href="#immediate-removal" aria-label="Permalink to &quot;Immediate Removal&quot;">​</a></h3><p>When you delete an extension, it is immediately removed from the platform and stops being served.</p><h2 id="what-this-means-for-your-code" tabindex="-1">What This Means for Your Code <a class="header-anchor" href="#what-this-means-for-your-code" aria-label="Permalink to &quot;What This Means for Your Code&quot;">​</a></h2><p>Most extension code works without any changes. Here is what to keep in mind:</p><table tabindex="0"><thead><tr><th>What you want to do</th><th>Works?</th><th>Notes</th></tr></thead><tbody><tr><td>Inline <code>&lt;script&gt;</code> tags (widgets)</td><td>Yes</td><td>Inline scripts are allowed by the security policy</td></tr><tr><td>Inline <code>&lt;style&gt;</code> tags (widgets)</td><td>Yes</td><td>Inline styles are allowed by the security policy</td></tr><tr><td>Relative asset paths (<code>./styles.css</code>)</td><td>Yes</td><td>Standard relative paths work as expected</td></tr><tr><td>Load from trusted libraries</td><td>Yes</td><td><code>cdn.jsdelivr.net</code>, <code>cdnjs.cloudflare.com</code>, <code>unpkg.com</code>, <code>esm.sh</code> are allowed</td></tr><tr><td>Load scripts from unknown domains</td><td>No</td><td>External scripts from untrusted sources are blocked</td></tr><tr><td>Use <code>eval()</code></td><td>No</td><td>Blocked by the Content Security Policy</td></tr><tr><td>Use <code>new Function()</code> from strings</td><td>No</td><td>Blocked by the Content Security Policy</td></tr><tr><td>Hardcode API keys or tokens</td><td>No</td><td>Detected as credential exposure — use Connectors instead</td></tr></tbody></table><h2 id="what-happens-when-content-is-rejected" tabindex="-1">What Happens When Content Is Rejected <a class="header-anchor" href="#what-happens-when-content-is-rejected" aria-label="Permalink to &quot;What Happens When Content Is Rejected&quot;">​</a></h2><p>If the platform detects a security issue in your code, the <strong>entire build fails</strong> — no extensions from that push are published. Previously published content remains available until a clean push succeeds.</p><p>The error message includes the category of the issue:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Widget &#39;my-widget&#39; rejected: content policy violation (categories: obfuscation)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="how-to-resolve-each-category" tabindex="-1">How to Resolve Each Category <a class="header-anchor" href="#how-to-resolve-each-category" aria-label="Permalink to &quot;How to Resolve Each Category&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Category</th><th>What to change</th></tr></thead><tbody><tr><td><code>crypto_mining</code></td><td>Remove cryptocurrency mining scripts entirely</td></tr><tr><td><code>data_exfiltration</code></td><td>Remove code that sends user data to external servers. If you need to send data, use a <a href="/docs/connectors/">Connector</a> instead</td></tr><tr><td><code>phishing_redirect</code></td><td>Remove fake login forms or deceptive redirects. Use your platform&#39;s built-in authentication</td></tr><tr><td><code>obfuscation</code></td><td>Replace obfuscated code with readable source. If you use a bundler, check that its output is not overly minified</td></tr><tr><td><code>external_script_loading</code></td><td>Load scripts from trusted sources only, or bundle dependencies into your widget directory</td></tr><tr><td><code>credential_exposure</code></td><td>Remove hardcoded secrets from your code. Use environment variables, a secrets manager, or <a href="/docs/connectors/">Connectors</a> to handle credentials securely</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./customization-guardrails.html">Customization Guardrails</a> — Best practices for writing extension code that passes these checks and survives platform updates</li><li><a href="./error-codes.html">Error Codes</a> — Full error reference including content scan rejections</li><li><a href="./build-and-publish.html">Build &amp; Publish</a> — The publishing pipeline</li><li><a href="./common-issues.html">Common Issues</a> — Common issues and solutions</li></ul>',35)])])}const m=t(d,[["render",r]]);export{p as __pageData,m as default};
